function isValidParens(s) {
  const stack = [];
  const openParens = { '(': 1, ')': -1, '[': 1, ']': -1, '{': 1, '}': -1 };

  for (const char of s) {
    if (openParens[char]) {
      stack.push(char);
    } else {
      const lastChar = stack.pop();
      if (openParens[lastChar] !== openParens[char]) {
        return false;
      }
    }
  }

  return stack.length === 0;
}

