function parseCsv(line) {
  const fields = [];
  let currentField = '';
  let inQuotes = false;
  for (const char of line) {
    if (char === ',') {
      if (inQuotes) {
        currentField += char;
      } else {
        if (currentField) {
          fields.push(currentField);
          currentField = '';
        }
      }
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else {
      currentField += char;
    }
  }
  if (currentField) {
    fields.push(currentField);
  }
  return fields;
}

